fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    // Since s1, s2, s3 have equal length, no need to check other lengths explicitly.
    // Result length is 3 * n.
    let mut res = Vec::with_capacity(3 * n);

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}